// Verification of the Jathagam engine against Swiss Ephemeris (SIDM_LAHIRI)
// reference charts generated by tools/gen_reference.py. Swiss Ephemeris is the
// engine used by Jagannatha Hora; local->UTC in the references was done with
// Python's zoneinfo, independently of the app's tz-lookup + Luxon path.
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { computeChart, localToUtc, zoneFor } from '../src/engine/index.js';
import { lagnam } from '../src/engine/astro.js';

const refs = JSON.parse(readFileSync(new URL('./reference-charts.json', import.meta.url)));
const sweep = JSON.parse(readFileSync(new URL('./reference-sweep.json', import.meta.url)));

const PLANET_TOL = 1.0; // arcminutes
const LAGNA_TOL = 3.0; // arcminutes
const arcmin = (a, b) => Math.abs(((a - b + 540) % 360) - 180) * 60;
const jdToDate = (jd) => new Date((jd - 2440587.5) * 86400000);
const PLANETS = ['sun', 'moon', 'mars', 'mercury', 'jupiter', 'venus', 'saturn'];

describe('reference charts (local time + place, end to end)', () => {
  for (const c of refs.charts) {
    describe(c.name, () => {
      const [date, time] = c.local.split(' ');
      const [year, month, day] = date.split('-').map(Number);
      const [hour, minute] = time.split(':').map(Number);

      it('resolves the IANA zone from lat/long', () => {
        expect(zoneFor(c.lat, c.lon)).toBe(c.zone);
      });

      const conv = localToUtc({ year, month, day, hour, minute }, zoneFor(c.lat, c.lon));
      it(`converts local time to UTC with the historical offset (${c.utcOffsetMinutes} min)`, () => {
        expect(conv.valid).toBe(true);
        expect(conv.offsetMinutes).toBe(c.utcOffsetMinutes);
        expect(conv.utc.toISOString().replace('.000', '')).toBe(c.utc);
      });

      for (const node of ['mean', 'true']) {
        it(`planet longitudes within ${PLANET_TOL}' (${node} node)`, () => {
          const chart = computeChart({ utc: conv.utc, lat: c.lat, lon: c.lon }, { node });
          const by = Object.fromEntries(chart.planets.map((p) => [p.key, p]));
          for (const k of PLANETS) {
            expect(arcmin(by[k].lon, c.ref[k].lon), k).toBeLessThan(PLANET_TOL);
            if (Math.abs(c.ref[k].speed) > 1e-3) expect(by[k].retro, `${k} vakram`).toBe(c.ref[k].speed < 0);
          }
          const rahuRef = c.ref[`rahu_${node}`].lon;
          expect(arcmin(by.rahu.lon, rahuRef), 'rahu').toBeLessThan(PLANET_TOL);
          expect(arcmin(by.ketu.lon, (rahuRef + 180) % 360), 'ketu').toBeLessThan(PLANET_TOL);
        });
      }

      it(`lagnam within ${LAGNA_TOL}'`, () => {
        const chart = computeChart({ utc: conv.utc, lat: c.lat, lon: c.lon });
        expect(arcmin(chart.lagnam.lon, c.ref.lagnam)).toBeLessThan(LAGNA_TOL);
      });

      it('ayanamsa matches Swiss Ephemeris Lahiri within 1"', () => {
        const chart = computeChart({ utc: conv.utc, lat: c.lat, lon: c.lon });
        expect(arcmin(chart.ayanamsa, c.ref.ayanamsa_mean) * 60).toBeLessThan(1);
      });

      it('panchangam elements agree with the reference Sun/Moon', () => {
        const chart = computeChart({ utc: conv.utc, lat: c.lat, lon: c.lon });
        const s = c.ref.sun.lon;
        const m = c.ref.moon.lon;
        const el = (((m - s) % 360) + 360) % 360;
        expect(chart.panchangam.thithi).toBe(Math.floor(el / 12));
        expect(chart.panchangam.yogam).toBe(Math.floor((((s + m) % 360) + 360) % 360 / (360 / 27)));
        expect(chart.summary.nakshatra).toBe(Math.floor(m / (360 / 27)));
        expect(chart.summary.rasi).toBe(Math.floor(m / 30));
      });
    });
  }
});

describe(`random sweep 1900-2050 (${sweep.length} instants, random places)`, () => {
  it('all grahas within 1\', lagnam within 3\'', () => {
    let worst = { p: 0, l: 0 };
    for (const r of sweep) {
      const utc = jdToDate(r.jdUT);
      for (const node of ['mean', 'true']) {
        const chart = computeChart({ utc, lat: r.lat, lon: r.lon }, { node });
        const by = Object.fromEntries(chart.planets.map((p) => [p.key, p]));
        for (const k of PLANETS) worst.p = Math.max(worst.p, arcmin(by[k].lon, r.ref[k].lon));
        worst.p = Math.max(worst.p, arcmin(by.rahu.lon, r.ref[`rahu_${node}`].lon));
      }
      worst.l = Math.max(worst.l, arcmin(lagnam(utc, r.lat, r.lon), r.ref.lagnam));
    }
    expect(worst.p).toBeLessThan(PLANET_TOL);
    expect(worst.l).toBeLessThan(LAGNA_TOL);
  });
});

describe('edge cases in time conversion', () => {
  it('India before 1955: Chennai 1943 uses war time UTC+6:30', () => {
    const r = localToUtc({ year: 1943, month: 8, day: 15, hour: 10, minute: 30 }, 'Asia/Kolkata');
    expect(r.offsetMinutes).toBe(390);
  });
  it('India 1931 uses IST UTC+5:30', () => {
    expect(localToUtc({ year: 1931, month: 3, day: 2, hour: 5, minute: 10 }, 'Asia/Kolkata').offsetMinutes).toBe(330);
  });
  it('US DST: New York July 1990 is EDT (UTC-4)', () => {
    expect(localToUtc({ year: 1990, month: 7, day: 4, hour: 21, minute: 45 }, 'America/New_York').offsetMinutes).toBe(-240);
  });
  it('US DST gap: 2:30 AM on 2008-03-09 in Chicago does not exist', () => {
    expect(localToUtc({ year: 2008, month: 3, day: 9, hour: 2, minute: 30 }, 'America/Chicago').note).toBe('nonexistent');
  });
  it('US DST overlap: 1:30 AM on 2008-11-02 in New York is ambiguous', () => {
    const r = localToUtc({ year: 2008, month: 11, day: 2, hour: 1, minute: 30 }, 'America/New_York');
    expect(r.note).toBe('ambiguous');
    expect(r.offsetMinutes).toBe(-240); // first occurrence (EDT)
  });
  it('US before the 2007 rule change: 1990-11-04 is standard time', () => {
    const r = localToUtc({ year: 1990, month: 11, day: 4, hour: 1, minute: 30 }, 'America/New_York');
    expect(r.offsetMinutes).toBe(-300);
    expect(r.note).toBeUndefined();
  });
});
